// Describe the screen, on request only.
//
// The harness reads RAM, so it already knows the party, the position and the
// battle state exactly -- better than a player does. This exists for the cases
// RAM does NOT answer: an unexpected cutscene, a menu it does not recognise, a
// sprite on screen it has no symbol for. Calling it every turn would be slower
// and worse than the reads it already has.
const req=$input.first().json, headers=req.headers||{}, body=req.body||{};
const expected=$env.DEX_SHARED_SECRET;
if (expected && headers['x-dex-secret']!==expected) throw new Error('Unauthorized: bad or missing x-dex-secret');
const image=body.image; if(!image) throw new Error('Missing image');
const question=String(body.question||'').trim();
const prompt=[
 `You are looking at a screenshot from a Game Boy Advance role-playing game.`,
 `Describe ONLY what is actually on screen. Do not guess at story, do not name`,
 `creatures you cannot read, and do not invent menu options that are not visible.`,
 question ? `The agent asked: ${question}` : `Say what is on screen and what the player can do next.`,
 `Answer in 1 to 3 short sentences. If a text box is open, quote its text exactly.`,
].join('\n');
return [{ json: { visionBody: {
  model: $env.DAEMONS_VISION_MODEL || $env.DEX_VISION_MODEL || 'default',
  messages:[{role:'user',content:[
    {type:'text',text:prompt},
    {type:'image_url',image_url:{url:`data:image/png;base64,${image}`}}]}],
  max_tokens:300, temperature:0.2, stream:false } } }];

const r=$input.first().json;
const raw=r?.choices?.[0]?.message?.content ?? r?.message?.content ?? '';
const description=String(raw).trim();
return [{ json: { description: description || null,
                  error: description ? null : 'no_description' } }];
